/**
 * Unicrab mascot rig (UNI-200) — pure logic shared by the web renderer
 * (components/Unicrab.tsx) and mirrored by the Android overlay
 * (UnicrabView.kt), which reads the same two JSON files:
 *
 * - `assets/unicrab/unicrab.sprite.json` — generated by
 *   `scripts/sprite-from-png.py` from the pixel-art PNG: palette, cells
 *   labelled by part, and eye masks. Never hand-edited.
 * - `assets/unicrab/unicrab.anim.json` — the animation table: per state,
 *   per part, whole-cell [dx, dy] offsets per frame + eye mask per frame.
 *
 * Nothing here is drawn frame by frame: every frame is the same sprite
 * with parts moved by whole cells, so it stays pixel art at any size.
 */
import spriteJson from '../assets/unicrab/unicrab.sprite.json';
import animJson from '../assets/unicrab/unicrab.anim.json';

export const PART_NAMES = ['legs-left', 'legs-right', 'body', 'claw-left', 'claw-right', 'visor', 'eye-left', 'eye-right'] as const;
export type PartName = (typeof PART_NAMES)[number];
export const EYE_MASKS = ['open', 'left', 'right', 'blink', 'closed', 'happy'] as const;
export type EyeMask = (typeof EYE_MASKS)[number];
/** Animated groups: `all` = everything, `torso` = body + visor + eyes, `zzz` = the sleep Z's. */
export const TRACKS = ['all', 'torso', 'claw-left', 'claw-right', 'legs-left', 'legs-right', 'zzz'] as const;
export type Track = (typeof TRACKS)[number];
export const MASCOT_STATES = ['idle', 'working', 'needs-you', 'done', 'offline', 'sleep'] as const;
export type MascotState = (typeof MASCOT_STATES)[number];

/** [x, y, paletteIndex] */
export type Cell = [number, number, number];
export type Sprite = {
  width: number;
  height: number;
  palette: string[];
  roles: { outline: number; visor: number[]; eye: number[] };
  parts: Record<PartName, Cell[]>;
  eyes: Record<EyeMask, Cell[]>;
};
export type Offset = [number, number];
export type StateAnim = {
  frameMs: number;
  tracks: Partial<Record<Track, Offset[]>>;
  eyes: EyeMask[];
  blink: boolean;
  opacity: number;
};
export type Anim = { blinkMs: number; blinkEvery: [number, number]; states: Record<MascotState, StateAnim> };

export const sprite = spriteJson as unknown as Sprite;
export const anim = animJson as unknown as Anim;

/** Room around the 24×20 sprite for hops, waves and the Z's (in cells). */
export const PAD = { left: 2, right: 3, top: 4, bottom: 1 } as const;
export const viewBox = (s: Sprite = sprite) => `${-PAD.left} ${-PAD.top} ${s.width + PAD.left + PAD.right} ${s.height + PAD.top + PAD.bottom}`;

/** Which track moves a part (torso parts follow `torso`; the rest their own). */
export function trackOf(part: PartName): Track {
  if (part === 'body' || part === 'visor' || part === 'eye-left' || part === 'eye-right') return 'torso';
  return part;
}

/** How many frames a state's loop has (the longest track / eye list). */
export function frameCount(a: StateAnim): number {
  return Math.max(1, a.eyes.length, ...Object.values(a.tracks).map((t) => t?.length ?? 0));
}

export function loopMs(a: StateAnim): number {
  return a.frameMs * frameCount(a);
}

/** The frame index at time `t` (ms since the state started). */
export function frameAt(a: StateAnim, t: number): number {
  const n = frameCount(a);
  return Math.floor(Math.max(0, t) / a.frameMs) % n;
}

/** A track's whole-cell offset at frame `i` (a short track holds its last value; a missing one is [0, 0]). */
export function offsetAt(a: StateAnim, track: Track, i: number): Offset {
  const t = a.tracks[track];
  if (!t?.length) return [0, 0];
  return t[Math.min(i, t.length - 1)]!;
}

/** The eye mask at frame `i`, with a blink overriding it. */
export function eyesAt(a: StateAnim, i: number, blinking = false): EyeMask {
  if (blinking && a.blink) return 'blink';
  return a.eyes[i % a.eyes.length] ?? 'open';
}

/** A random delay until the next blink, in [blinkEvery[0], blinkEvery[1]). */
export function nextBlinkDelay(rand: () => number = Math.random, a: Anim = anim): number {
  const [lo, hi] = a.blinkEvery;
  return Math.round(lo + rand() * (hi - lo));
}

const kfName = (state: MascotState, what: string) => `uc-${state}-${what}`;

/**
 * CSS for every state: one `@keyframes` per animated track and per eye
 * mask, holding each frame (`steps(1, end)` between keyframes) and moving
 * by whole sprite cells — CSS px on SVG content are user units = cells.
 * Selectors are scoped by `[data-state]` on the `.unicrab` root.
 */
export function keyframesCss(a: Anim = anim): string {
  const out: string[] = [];
  const pct = (i: number, n: number) => `${+((i / n) * 100).toFixed(3)}%`;
  for (const state of MASCOT_STATES) {
    const s = a.states[state];
    const n = frameCount(s);
    const dur = `${loopMs(s)}ms`;
    for (const track of TRACKS) {
      const t = s.tracks[track];
      if (!t?.length) continue;
      const frames = Array.from({ length: n }, (_, i) => offsetAt(s, track, i));
      if (frames.every(([x, y]) => x === 0 && y === 0)) continue;
      const name = kfName(state, track);
      out.push(`@keyframes ${name}{${frames.map(([x, y], i) => `${pct(i, n)}{transform:translate(${x}px,${y}px)}`).join('')}100%{transform:translate(${frames[0]![0]}px,${frames[0]![1]}px)}}`);
      out.push(`.unicrab[data-state="${state}"] [data-track="${track}"]{animation:${name} ${dur} steps(1,end) infinite}`);
    }
    // Eye masks: each mask used by the state is visible on its frames only.
    const used = [...new Set(s.eyes)];
    for (const mask of EYE_MASKS) {
      const sel = `.unicrab[data-state="${state}"] [data-eyes="${mask}"]`;
      if (!used.includes(mask)) {
        // `blink` is shown by the JS blink timer through [data-blink] instead.
        out.push(`${sel}{visibility:hidden}`);
        continue;
      }
      if (used.length === 1) {
        out.push(`${sel}{visibility:visible}`);
        continue;
      }
      const name = kfName(state, `eyes-${mask}`);
      const frames = Array.from({ length: n }, (_, i) => s.eyes[i % s.eyes.length] === mask);
      out.push(`@keyframes ${name}{${frames.map((on, i) => `${pct(i, n)}{visibility:${on ? 'visible' : 'hidden'}}`).join('')}}`);
      out.push(`${sel}{visibility:${frames[0] ? 'visible' : 'hidden'};animation:${name} ${dur} steps(1,end) infinite}`);
    }
    out.push(`.unicrab[data-state="${state}"]{opacity:${s.opacity}}`);
    if (s.blink) {
      out.push(`.unicrab[data-state="${state}"][data-blink] [data-eyes]{visibility:hidden;animation:none}`);
      out.push(`.unicrab[data-state="${state}"][data-blink] [data-eyes="blink"]{visibility:visible}`);
    }
  }
  out.push('.unicrab [data-track="zzz"]{display:none}', '.unicrab[data-state="sleep"] [data-track="zzz"]{display:inline}');
  // Reduced motion: frame 0 of every state, no blinking (style.css also stops all animations).
  out.push('@media (prefers-reduced-motion: reduce){.unicrab [data-track],.unicrab [data-eyes]{animation:none !important}}');
  return out.join('\n');
}

/** Pixel "z" glyphs for the sleep state: a 4×4 Z above the right claw and a small one beside it, in cells (inside PAD). */
export function zzzCells(s: Sprite = sprite): Cell[] {
  const eye = s.roles.eye[0] ?? 0;
  const z = (x: number, y: number, size: number): Cell[] => {
    const cells: Cell[] = [];
    for (let i = 0; i < size; i++) cells.push([x + i, y, eye], [x + i, y + size - 1, eye]);
    for (let i = 1; i < size - 1; i++) cells.push([x + size - 1 - i, y + i, eye]);
    return cells;
  };
  return [...z(s.width - 4, -4, 4), ...z(s.width, 0, 3)];
}

// ── Which state the mascot shows ──────────────────────────────────────

export type MascotInputs = {
  /** Paired hosts. */
  hosts: number;
  /** Hosts whose last chat_list failed with no data. */
  offlineHosts: number;
  /** Unread "waiting" items (ask_user, permission, input…). */
  waiting: number;
  /** Unread "finished" items. */
  finished: number;
  /** Agents working right now (chat_list). */
  running: number;
  /** ms since anything changed (an item arrived, an agent started/stopped, the user touched the mascot). */
  quietMs: number;
};

/** Idle this long → the crab falls asleep. */
export const SLEEP_AFTER_MS = 5 * 60_000;

/** Priority: something waits on you > a run just finished > working > all PCs unreachable > idle/asleep. */
export function mascotState(i: MascotInputs): MascotState {
  if (i.waiting > 0) return 'needs-you';
  if (i.finished > 0) return 'done';
  if (i.running > 0) return 'working';
  if (i.hosts > 0 && i.offlineHosts >= i.hosts) return 'offline';
  if (i.quietMs >= SLEEP_AFTER_MS) return 'sleep';
  return 'idle';
}

export const STATE_LABEL: Record<MascotState, string> = {
  idle: 'All quiet',
  working: 'Working',
  'needs-you': 'Needs you',
  done: 'Finished',
  offline: 'PCs offline',
  sleep: 'Asleep',
};
